using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class OffersPage:UserControl{DataGridView grid;public OffersPage(){BackColor=Theme.Background;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};var add=Ui.Button(L.Fa?"پیشنهاد جدید":"New offer");var accept=Ui.Button(L.Fa?"علامت‌گذاری پذیرفته":"Mark accepted",false);var refresh=Ui.Button(L.T("refresh"),false);add.Click+=(s,e)=>NewOffer();accept.Click+=(s,e)=>SetStatus("Accepted");refresh.Click+=(s,e)=>LoadData();bar.Controls.Add(add);bar.Controls.Add(accept);bar.Controls.Add(refresh);grid=Ui.Grid();Controls.Add(grid);Controls.Add(bar);grid.BringToFront();LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT o.Id,c.FullName AS Candidate,j.Title AS Job,o.Salary,o.StartDate,o.ExpiryDate,o.Status,o.CreatedAt FROM Offers o JOIN Applications a ON a.Id=o.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY o.Id DESC");}void NewOffer(){using(var f=new Form{Text=L.Fa?"پیشنهاد استخدام":"Employment offer",Size=new Size(460,360),StartPosition=FormStartPosition.CenterParent}){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(20)};var app=Ui.Text();app.Width=380;app.Tag="Application ID";var salary=Ui.Text();salary.Width=380;salary.Tag=L.Fa?"حقوق پیشنهادی":"Salary";var start=new DateTimePicker{Width=380};var expiry=new DateTimePicker{Width=380,Value=DateTime.Today.AddDays(7)};var b=Ui.Button(L.T("save"));b.Click+=(s,e)=>{int id;decimal sal;if(!int.TryParse(app.Text,out id)||!decimal.TryParse(salary.Text,out sal)){MessageBox.Show(L.Fa?"شناسه درخواست و حقوق را صحیح وارد کنید":"Enter a valid application ID and salary");return;}Database.Exec("INSERT Offers(ApplicationId,Salary,StartDate,ExpiryDate,Status,CreatedBy) VALUES(@a,@s,@d,@e,'Draft',@u)",new SqlParameter("@a",id),new SqlParameter("@s",sal),new SqlParameter("@d",start.Value),new SqlParameter("@e",expiry.Value),new SqlParameter("@u",AppSession.UserId));Database.Audit("Create","Offer","Application "+id);f.DialogResult=DialogResult.OK;f.Close();};p.Controls.Add(Ui.Label(L.Fa?"شناسه درخواست":"Application ID"));p.Controls.Add(app);p.Controls.Add(Ui.Label(L.Fa?"حقوق":"Salary"));p.Controls.Add(salary);p.Controls.Add(Ui.Label(L.Fa?"تاریخ شروع":"Start date"));p.Controls.Add(start);p.Controls.Add(Ui.Label(L.Fa?"اعتبار تا":"Expires"));p.Controls.Add(expiry);p.Controls.Add(b);f.Controls.Add(p);Theme.Apply(f);if(f.ShowDialog()==DialogResult.OK)LoadData();}}void SetStatus(string s){if(grid.CurrentRow==null)return;var id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);Database.Exec("UPDATE Offers SET Status=@s WHERE Id=@i",new SqlParameter("@s",s),new SqlParameter("@i",id));LoadData();}}}
